#!/usr/bin/env python3
"""Generate UnitInfo lists and their LoadUnits event scripts.

usage: process.py INDEX OUT_C OUT_H   (INDEX lists unit files in ROM order)

    [Name] nocamera script=OtherName
    PID class=JID lead=PID auto red lv=1 at=X,Y to=X,Y items=IID,-,IID ai=AI_A_03,AI_B_03
"""
import os, re, sys

FACTIONS = {"blue": "FACTION_ID_BLUE", "red": "FACTION_ID_RED", "green": "FACTION_ID_GREEN"}

C_HEADER = """\
// Generated by tools/unitinfo/process.py from data/unitinfo; edit those files instead.

#include "chapterunits.h"

#include "event.h"
#include "eventscript.h"
#include "unit.h"
#include "faction.h"
#include "ai.h"

#include "constants/pids.h"
#include "constants/jids.h"
#include "constants/iids.h"
"""

H_HEADER = """\
#pragma once

#include "prelude.h"

#include "event.h"
#include "unit.h"
"""


class ParseError(Exception):
    pass


def parse_pos(value):
    m = re.fullmatch(r"(\d+),(\d+)", value)
    if not m:
        raise ParseError(f"bad position {value!r}")
    return m.groups()


def parse_unit(line):
    tokens = line.split()
    unit = {"pid": "PID_" + tokens[0], "jid": "0", "lead": "0", "auto": "FALSE", "items": ["0"], "ai": ["0"]}

    for token in tokens[1:]:
        key, eq, value = token.partition("=")
        if not eq:
            if token == "auto":
                unit["auto"] = "TRUE"
            elif token in FACTIONS:
                unit["faction"] = FACTIONS[token]
            else:
                raise ParseError(f"unknown flag {token!r}")
        elif key == "class":
            unit["jid"] = "JID_" + value
        elif key == "lead":
            unit["lead"] = "PID_" + value
        elif key == "lv":
            unit["level"] = value
        elif key == "at":
            unit["load"] = parse_pos(value)
        elif key == "to":
            unit["move"] = parse_pos(value)
        elif key == "items":
            unit["items"] = ["0" if item == "-" else "IID_" + item for item in value.split(",")]
        elif key == "ai":
            unit["ai"] = value.split(",")
        else:
            raise ParseError(f"unknown field {key!r}")

    for key in ("faction", "level", "load", "move"):
        if key not in unit:
            raise ParseError(f"missing {key}")

    return "{{ {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {{ {} }}, {{ {} }} }},".format(
        unit["pid"], unit["jid"], unit["lead"], unit["auto"], unit["faction"], unit["level"],
        *unit["load"], *unit["move"], ", ".join(unit["items"]), ", ".join(unit["ai"]))


def parse_list_header(line):
    m = re.fullmatch(r"\[(\w+)\]((?:\s+\S+)*)", line)
    if not m:
        raise ParseError("bad list header")
    entry = {"name": m.group(1), "script": m.group(1), "nocamera": False, "units": []}
    for token in m.group(2).split():
        if token == "nocamera":
            entry["nocamera"] = True
        elif token.startswith("script="):
            entry["script"] = token[len("script="):]
        else:
            raise ParseError(f"unknown list option {token!r}")
    return entry


def parse_file(path):
    lists = []
    with open(path, encoding="utf-8") as f:
        for lineno, raw in enumerate(f, 1):
            line = raw.split("#", 1)[0].strip()
            if not line:
                continue
            try:
                if line.startswith("["):
                    lists.append(parse_list_header(line))
                elif not lists:
                    raise ParseError("unit before any list header")
                else:
                    lists[-1]["units"].append(parse_unit(line))
            except ParseError as e:
                sys.exit(f"{path}:{lineno}: {e}")
    return lists


def main():
    index, out_c, out_h = sys.argv[1:4]
    base = os.path.dirname(index)

    with open(index, encoding="utf-8") as f:
        files = [line.strip() for line in f if line.strip() and not line.startswith("#")]

    c, h = [C_HEADER], [H_HEADER]

    for i, name in enumerate(files):
        lists = parse_file(os.path.join(base, name))
        if i:
            h.append("")

        for entry in lists:
            units = "".join(f"    {unit}\n" for unit in entry["units"])
            c.append(f"\nstruct UnitInfo CONST_DATA UnitInfo_{entry['name']}[] =\n{{\n{units}    {{ 0 }}, // end\n}};\n")
            h.append(f"extern struct UnitInfo CONST_DATA UnitInfo_{entry['name']}[];")

        for entry in lists:
            prefix = "    EvtUnitCameraOff\n    EvtNoSkip\n" if entry["nocamera"] else ""
            c.append(f"\nEventScr CONST_DATA EventScr_LoadUnits_{entry['script']}[] =\n{{\n{prefix}"
                     f"    EvtLoadUnits(UnitInfo_{entry['name']})\n    EvtMoveWait\n    EvtClearSkip\n    EvtEnd\n}};\n")
            h.append(f"extern EventScr CONST_DATA EventScr_LoadUnits_{entry['script']}[];")

    with open(out_c, "w", encoding="utf-8") as f:
        f.write("".join(c))
    with open(out_h, "w", encoding="utf-8") as f:
        f.write("\n".join(h) + "\n")


if __name__ == "__main__":
    main()
